#!/usr/bin/env python3
"""Publiceer gecontroleerde TR-koppelingen voor Mattheüs 23."""
from __future__ import annotations
import argparse, json
from pathlib import Path
from rebuild_johannes2_tr_strongs import mapping, r
from rebuild_nt_tr_strongs import load_tr_chapter
ROOT = Path(__file__).resolve().parents[1]
SPECS = {
1:[("Toen sprak Jezus tot de menigten en tot Zijn discipelen,",r(0,9))],2:[("Zeggende: De Schriftgeleerden en de Farizeën zijn gezeten op de stoel van Mozes;",r(0,10))],3:[("Daarom, al wat zij u zeggen, dat u houden zult, houdt dat en doet het; maar doet niet naar hun werken; want zij zeggen het, en doen het niet.",r(0,21))],4:[("Want zij binden lasten, die zwaar zijn en kwalijk om te dragen, en leggen ze op de schouders van de mensen; maar zij willen die met hun vinger niet verroeren.",r(0,20))],5:[("En al hun werken doen zij, om van de mensen gezien te worden; want zij maken hun gebedsriemen breed, en maken de zomen van hun kleren groot.",r(0,22))],6:[("En zij houden van de vooraanzitting in de maaltijden, en de voorgestoelten in de synagogen;",r(0,12))],7:[("Ook de begroetingen op de markten, en van de mensen genoemd te worden: Rabbi, Rabbi!",r(0,12))],8:[("Maar u zult niet Rabbi genoemd worden; want Eén is uw Meester, namelijk Christus; en u bent allen broeders.",r(0,17))],9:[("En u zult niemand uw vader noemen op de aarde; want Eén is uw Vader, namelijk Die in de hemelen is.",r(0,17))],10:[("Noch zult u meesters genoemd worden; want Eén is uw Meester, namelijk Christus.",r(0,10))],11:[("Maar de meeste van u zal uw dienaar zijn.",r(0,6))],12:[("En wie zichzelf verhogen zal, die zal vernederd worden; en wie zichzelf zal vernederen, die zal verhoogd worden.",r(0,9))],13:[("Maar wee u, u Schriftgeleerden en Farizeën, u huichelaars! want u sluit het Koninkrijk van de hemelen voor de mensen, omdat u daar niet ingaat, noch degenen, die ingaan zouden, laat ingaan.",r(0,24))],14:[("Wee u, u Schriftgeleerden en Farizeën, u huichelaars, want u eet de huizen van de weduwen op, en dat onder de schijn van lang te bidden; daarom zult u te zwaarder oordeel ontvangen.",r(0,19))],15:[("Wee u, u Schriftgeleerden en Farizeën, u huichelaars, want u omreist zee en land, om een Jodengenoot te maken, en als hij het geworden is, zo maakt u hem een kind van de hel, tweemaal meer dan u bent.",r(0,24))],16:[("Wee u, u blinde leidslieden, die zegt: Zo wie gezworen zal hebben bij de tempel, dat is niets; maar zo wie gezworen zal hebben bij het goud van de tempel, die is schuldig.",r(0,23))],17:[("U dwazen en blinden, want wat is meerder, het goud, of de tempel, die het goud heiligt?",r(0,15))],18:[("En zo wie gezworen zal hebben bij het altaar, dat is niets; maar zo wie gezworen zal hebben bij de gave, die daarop is, die is schuldig.",r(0,19))],19:[("U dwazen en blinden, want wat is meerder, de gave, of het altaar, dat de gave heiligt?",r(0,14))],20:[("Daarom wie zweert bij het altaar, die zweert bij hetzelfde, en bij al wat daarop is.",r(0,14))],21:[("En wie zweert bij de tempel, die zweert daarbij, en bij Die, Die daarin woont.",r(0,13))],22:[("En wie zweert bij de hemel, die zweert bij de troon van God, en bij Die, Die daarop zit.",r(0,17))],23:[("Wee u, u Schriftgeleerden en Farizeën, u huichelaars, want u vertient de munte, en de dille, en de komijn, en u laat na het zwaarste van de wet, namelijk het oordeel, en de barmhartigheid, en het geloof. Deze dingen moest men doen, en de andere niet nalaten.",r(0,35))],24:[("U blinde leidslieden, die de mug uitzijgt, en de kameel doorzwelgt.",r(0,9))],25:[("Wee u, u Schriftgeleerden en Farizeën, u huichelaars, want u reinigt het buitenste van de drinkbeker, en van de schotel, maar van binnen zijn zij vol van roof en onmatigheid.",r(0,21))],26:[("U blinde Farizeër, reinig eerst wat binnen in de drinkbeker en de schotel is, opdat ook het buitenste daarvan rein wordt.",r(0,17))],27:[("Wee u, u Schriftgeleerden en Farizeën, u huichelaars, want u bent de witgepleisterden graven gelijk, die van buiten wel schoon schijnen, maar van binnen zijn zij vol doodsbeenderen en alle onreinheid.",r(0,22))],28:[("Zo ook schijnt u wel de mensen van buiten rechtvaardig, maar van binnen bent u vol huichelarij en ongerechtigheid.",r(0,15))],29:[("Wee u, u Schriftgeleerden en Farizeën, u huichelaars, want u bouwt de graven van de profeten op, en versiert de graftekenen van de rechtvaardigen;",r(0,17))],30:[("En zegt: Als wij in de tijden van onze vaders waren geweest, wij zouden met hen geen gemeenschap gehad hebben aan het bloed van de profeten.",r(0,19))],31:[("Zo getuigt u tegen uzelf, dat u kinderen bent van degenen, die de profeten gedood hebben.",r(0,9))],32:[("U dan ook, vervult de mate van uw vaderen!",r(0,7))],33:[("U slangen, u adderengebroed! hoe zou u de helse verdoemenis ontvluchten?",r(0,9))],34:[("Daarom ziet, Ik zend tot u profeten, en wijzen, en schriftgeleerden, en daaruit zult u sommigen doden en kruisigen, en sommigen daaruit zult u geselen in uw synagogen, en zult hen vervolgen van stad tot stad;",r(0,31))],35:[("Opdat op u kome al het rechtvaardige bloed, dat vergoten is op de aarde, van het bloed van de rechtvaardige Abel af, tot op het bloed van Zacharia, de zoon van Barachia, die u gedood hebt tussen de tempel en het altaar.",r(0,30))],36:[("Voorwaar zeg Ik u: Al deze dingen zullen komen over dit geslacht.",r(0,9))],37:[("Jeruzalem, Jeruzalem! u, die de profeten doodt, en stenigt, die tot u gezonden zijn! hoe dikwijls heb Ik uw kinderen willen bijeenvergaderen, zoals een hen haar kuikens bijeenvergadert onder de vleugels; en u hebt niet gewild.",r(0,30))],38:[("Zie, uw huis wordt u woest gelaten.",r(0,6))],39:[("Want Ik zeg u: U zult Mij van nu aan niet zien, totdat u zeggen zult: Gezegend is Hij, Die komt in de Naam van de Heere!",r(0,17))],}
def build(utr_path:Path,osis_path:Path,write=False):
 source=load_tr_chapter(utr_path,osis_path,chapter=23,osis_book='Matt');p=ROOT/'data'/'mattheus'/'23.json';d=json.loads(p.read_text(encoding='utf8'));rt=max(SPECS);review={'book':'mattheus','chapter':23,'reviewed_through':rt,'verses':{},'tekstvarianten':{'23:14':'UTR bevat de langere versvorm; OSIS levert de precies corresponderende 20-tokenstroom.'}}
 for v in d['verses'][:rt]:
  n=int(v['number']);ts=source[n];gs=SPECS[n];ids=[i for _,x in gs for i in x]
  if sorted(ids)!=list(range(len(ts))) or len(ids)!=len(set(ids)):raise ValueError(f'Mattheüs 23:{n}: onvolledige of dubbele handmatige review')
  v['grondtekst']=[{'woord':t['woord'],'strongs':t['display_strong'],'lemma_strongs':t['lemma_strong'],'morfologie':t['morphology'],**({'tvm':t['tvm']} if t.get('tvm') else {})} for t in ts];v['woordnummers']=[mapping(a,x,ts,n) for a,x in gs]
  for item in v['woordnummers']:item['herkomst']['referentie']=f'MAT 23:{n}'
  review['verses'][str(n)]=[{'tekst':a,'bronindices':x,'reviewstatus':'handmatig_gecontroleerd'} for a,x in gs]
 if write:
  p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8');(ROOT/'data'/'woordnummers-review'/'mattheus-23.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n',encoding='utf8');ip=ROOT/'data'/'woordnummers-inline'/'mattheus.json';i=json.loads(ip.read_text(encoding='utf8'));i['chapters']['23']={str(v['number']):v['woordnummers'] for v in d['verses'][:rt]};ip.write_text(json.dumps(i,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 return {'verses':rt,'tokens':sum(len(source[n]) for n in range(1,rt+1))}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--utr',type=Path,required=True);p.add_argument('--osis',type=Path,required=True);p.add_argument('--write',action='store_true');a=p.parse_args();print(json.dumps(build(a.utr,a.osis,a.write),indent=2))
